import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class FirstSeenFilterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object guard(String label, java.util.concurrent.Callable<Object> body) {
        try {
            return body.call();
        } catch (Exception e) {
            return "<threw " + e.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        List<String> emails = Arrays.asList("a@Mail.com", "b@shop.org", "c@mail.COM", "d@shop.org", "e@news.net");
        check("firstPerDomain(mixed case)", "[a@Mail.com, b@shop.org, e@news.net]",
                String.valueOf(guard("fpd", () -> FirstSeenFilter.firstPerDomain(emails))));
        check("firstPerDomain(empty)", "[]",
                String.valueOf(guard("fpd2", () -> FirstSeenFilter.firstPerDomain(Arrays.asList()))));
        check("firstPerDomain(no at-sign share one domain)", "[plain, x@a.com]",
                String.valueOf(guard("fpd3", () -> FirstSeenFilter.firstPerDomain(
                        Arrays.asList("plain", "also-plain", "x@a.com")))));

        check("distinctByKey on word lengths", "[ant, bear, hippo]",
                String.valueOf(guard("dbk1", () -> Arrays.asList("ant", "bear", "crow", "hippo", "cat")
                        .stream()
                        .filter(FirstSeenFilter.distinctByKey(String::length))
                        .collect(Collectors.toList()))));
        check("distinctByKey on first letter", "[apple, banana]",
                String.valueOf(guard("dbk2", () -> Arrays.asList("apple", "avocado", "banana", "blue")
                        .stream()
                        .filter(FirstSeenFilter.distinctByKey(s -> s.charAt(0)))
                        .collect(Collectors.toList()))));
        check("distinctByKey on Integer remainder", "[10, 11, 12]",
                String.valueOf(guard("dbk3", () -> Arrays.asList(10, 11, 12, 13, 14, 15)
                        .stream()
                        .filter(FirstSeenFilter.distinctByKey(n -> n % 3))
                        .collect(Collectors.toList()))));
        check("each distinctByKey call gets a fresh set", "[apple, banana]",
                String.valueOf(guard("dbk4", () -> Arrays.asList("apple", "banana")
                        .stream()
                        .filter(FirstSeenFilter.distinctByKey(s -> s.charAt(0)))
                        .collect(Collectors.toList()))));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

