import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;

/**
 * TASK: Stream.distinct() compares whole elements. Build the missing
 * "distinct by a key" tool instead.
 *
 * distinctByKey(keyFn) returns a stateful Predicate that answers true the
 * FIRST time it sees a key and false for every later element with that key,
 * so it can be dropped straight into stream.filter(...).
 *
 * firstPerDomain(emails) uses it to keep only the first email address for
 * each domain, comparing domains case-insensitively but returning the
 * addresses exactly as they were given.
 *
 * Example: ["a@Mail.com", "b@shop.org", "c@mail.COM"]
 *       -> ["a@Mail.com", "b@shop.org"]
 *
 * EDGE CASE: an address with no "@" has an empty domain; all such addresses
 * share that one empty domain, so only the first of them survives.
 */
public class FirstSeenFilter {

    public static <T, K> Predicate<T> distinctByKey(Function<? super T, K> keyFn) {
        java.util.Set<K> seen = new java.util.HashSet<>();
        return value -> seen.add(keyFn.apply(value));
    }

    public static List<String> firstPerDomain(List<String> emails) {
        return emails.stream()
                .filter(distinctByKey(FirstSeenFilter::domainOf))
                .collect(java.util.stream.Collectors.toList());
    }

    private static String domainOf(String email) {
        int at = email.indexOf('@');
        return at < 0 ? "" : email.substring(at + 1).toLowerCase();
    }
}
